fields.InputDefinition:
{
  "goal": "Switch to the Knowledge Hub app via the application switcher dropdown next to the logo, then click 'Tags' in the left nav (fa-sitemap icon). This shared setup is done ONCE. Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) taxonomy-tree — in the 'Taxonomy' section on the 'Tree' sub-tab, click a tag node in the tree and confirm the right details panel populates with that tag's stats (Items Tagged, Avg Weight, Children, Depth) and its action toolbar (Add Child / Rename / Move / Merge Into) — if the taxonomy is empty, the tree panel with an empty-state and 'Add root tag' (+) control is a pass; (2) synonym-round-trip — with a tag selected, in its 'Synonyms' section type a new synonym (e.g. 'genai-test') into the add-synonym input and click '+ Add', confirm it appears in the list, then click its remove (x) control and confirm it disappears; (3) rebuild-embeddings — switch to the 'Health' section and click the 'Rebuild stale embeddings' button, confirming it is accepted (button enters a Rebuilding/disabled state OR a completion/status message appears; a no-stale result also counts); (4) library-search-drilldown — go to the 'Tag Library' section, type a term in the 'Search tags...' box and confirm the tag table narrows (or shows a valid no-match state), then clear it and click a tag row to open a drill-down of its content items (or a clear empty state). You do NOT need long-running actions to finish. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 65,
  "checkpoints": [
    {
      "name": "taxonomy-tree",
      "instruction": "taxonomy tree node select populates details",
      "visualCriteria": [
        "The Taxonomy Tree view shows a tree panel plus a details panel, and clicking a tree node populates the right details panel with tag stats and an action toolbar — OR an empty taxonomy shows the tree with an 'Add root tag' control"
      ]
    },
    {
      "name": "synonym-round-trip",
      "instruction": "add then remove a synonym",
      "visualCriteria": [
        "A selected tag's Synonyms editor has an add-synonym input and Add button; adding a synonym makes it appear in the tag's synonym list, and removing it makes it disappear (a full round-trip)"
      ]
    },
    {
      "name": "rebuild-embeddings",
      "instruction": "rebuild stale embeddings accepted",
      "visualCriteria": [
        "The Tags Health section renders with its health cards and a 'Rebuild stale embeddings' button, and clicking it transitions the button to a Rebuilding/disabled state or produces a status/completion message"
      ]
    },
    {
      "name": "library-search-drilldown",
      "instruction": "tag library search narrows + drilldown opens",
      "visualCriteria": [
        "Typing in the Tag Library 'Search tags...' box narrows the tag table to matching rows (or a valid no-match state), and clicking a tag row opens a drill-down listing its content items (or a clear empty state for that tag)"
      ]
    }
  ]
}
